import {panelKey,panelIntervals} from './portal-state.js';
import * as THREE from '../vendor/three.module.js';
export const PANEL_STEP=.25,SLATS=12,SLAT_PITCH=.014,RECESS=.3;
const insideOf=p=>({N:1,S:-1,W:-1,E:1}[p.face]);
export function poseSlats(hinges,height,amount,inside){const len=height/SLATS,pitch=SLAT_PITCH+(len-SLAT_PITCH)*amount,angle=Math.acos(pitch/len),depth=Math.sin(angle)*len,spacing=pitch+.013*Math.sin(angle),top=.16+height+SLATS*(SLAT_PITCH+.013)*(1-amount),base=top-SLATS*spacing;hinges.forEach((hinge,i)=>{hinge.position.set(0,base+i*spacing,(RECESS+(i%2?depth:0))*inside);hinge.rotation.x=(i%2?-angle:angle)*inside;});}
export function addAdaptivePortal(view,portal,body,p){const group=new THREE.Group();portal.add(group);group.userData.wallRole='opening-infill';const bays=[];for(const {a,b}of panelIntervals(p)){const bank=new THREE.Group();group.add(bank);bank.position.x=(a+b)/2-(p.a+p.b)/2;const hinges=[];for(let i=0;i<SLATS;i++){const h=new THREE.Group();bank.add(h);const left=a>p.a?.06:0,right=b<p.b?.06:0;view.cube(h,-(b-a)/2+left,0,-.006,b-a-left-right,p.height/SLATS,.012,'wall');hinges.push(h);}bays.push({a,b,hinges,amount:null});}(view.adaptivePortals??=[]).push({id:body.id,port:p,group,bays});}
export function renderAdaptivePortals(view){for(const portal of view.adaptivePortals??[])for(const bay of portal.bays){const next=view.sim.portalAmounts[panelKey(portal.id,portal.port,bay.a)]??1;if(bay.amount===next)continue;bay.amount=next;poseSlats(bay.hinges,portal.port.height,bay.amount,insideOf(portal.port));}}
